#endif

iNliNE half4 multiLayerBlendingStage()
{
	#pragma nu2_use(fs_local, fs_layer0_color)
	#if defined(PRELIGHT_FX) && (LIGHTMAP_STAGE == DISABLE)
		half4 baseColor = half4(1.0, 1.0, 1.0, fs_layer0_color.a);
	#else
		half4 baseColor = fs_layer0_color;
	#endif
	
	half4 surfaceColor;
	#if !defined(COMBINE_OP_0)
		#pragma nu2_use(uniform, layer0_diffuse)
		surfaceColor = layer0_diffuse * baseColor;
	#endif

	#pragma nu2_use(uniform, layer_kOpacities)
	#if defined(COMBINE_OP_0)
		#if defined(LAYER0_DIFFUSEENABLE)
			#if (PIXEL_SHADER_VERSION == 11)
				half4 colorLayer0 = baseColor;
			#else
				#if (LIGHTING_STAGE == DISABLE)
					// The material colour has already been combined with the vertex colour in the exporter prelighting.
					half4 colorLayer0 = baseColor;
				#else
					#pragma nu2_use(uniform, layer0_diffuse)
					half4 colorLayer0 = layer0_diffuse * baseColor;
				#endif
				colorLayer0.a *= layer_kOpacities.r;
			#endif
		#else
			// texture base 0
			#pragma nu2_use(uniform, layer0_sampler)
			#pragma nu2_use(varying, * LAYER0_UVSET)
			#if defined(USE_fs_stOffset)
				half4 colorLayer0 = tex2D(layer0_sampler, LAYER0_UVSET + fs_stOffset);
			#else
				#if defined(TEXTURE_ANIMATION_MAP)
					#pragma nu2_use(uniform, texAnimMap_sampler)
					#pragma nu2_use(uniform, texAnimCurves_sampler)

					half4 dmap = tex2D(texAnimMap_sampler, LAYER0_UVSET);
					#if defined(WIND)
						#pragma nu2_use(varying, varying_wind);
						half2 uv = half2(frac(varying_wind.w*dmap.a*20.0), dmap.b);
					#else
						#pragma nu2_use(uniform, time)
						#pragma nu2_use(varying, varying_plantParams);
						half2 uv = half2(frac(time.x*dmap.a*varying_plantParams.r), dmap.b);
					#endif
			
					half s = tex2D(texAnimCurves_sampler, uv).r;
					half4 colorLayer0 = tex2D(layer0_sampler, lerp(LAYER0_UVSET, LAYER0_UVSET + dmap.rg, s));
				#else
					half4 colorLayer0 = tex2D(layer0_sampler, LAYER0_UVSET);
				#endif
			#endif
			#if (PIXEL_SHADER_VERSION == 11)
				colorLayer0 *= baseColor;
			#else
				#pragma nu2_use(uniform, layer0_diffuse)
				colorLayer0.a *= (layer0_diffuse.a * layer_kOpacities.r);
				colorLayer0 *= baseColor;
			#endif
		#endif
		
		surfaceColor = colorLayer0;
	#endif
	
	#if defined(CAR_PAINT)
		#pragma nu2_use(fs_local, fs_normal)
		#pragma nu2_use(fs_local, fs_incident)
		#pragma nu2_use(fs_local, fs_lightDir0)
		#pragma nu2_use(uniform, carpaint_tints)
		#pragma nu2_use(uniform, carpaint_params)
		half ndotl = max( dot(fs_normal, fs_lightDir0.xyz), 0 );
		half ndotv = abs( dot(fs_normal, fs_incident) );
		ndotl = pow( ndotl, carpaint_params.g );
		ndotv = pow( ndotv, carpaint_params.r );	
		half3 paintTint = lerp( lerp(carpaint_tints[0],carpaint_tints[1],ndotl), lerp(carpaint_tints[2],carpaint_tints[3],ndotl), ndotv );
		paintTint = paintTint * 2.0 - 1.0;
		surfaceColor.rgb += paintTint;
	#endif
	
	#if defined(COMBINE_OP_1)
		// texture blend 1
		#define USE_combine
		#pragma nu2_use(uniform, layer1_diffuse)
		#pragma nu2_use(fs_local, fs_layer1_alpha)
		
		#if defined(LAYER1_DIFFUSEENABLE)
			half4 colorLayer1 = layer1_diffuse;
		#else
			#pragma nu2_use(uniform, layer1_sampler)
			#pragma nu2_use(varying, * LAYER1_UVSET)
			#if defined(USE_fs_stOffset)
			half4 colorLayer1 = tex2D(layer1_sampler, LAYER1_UVSET + fs_stOffset);
			#else
			half4 colorLayer1 = tex2D(layer1_sampler, LAYER1_UVSET);
			#endif
			colorLayer1.a *= layer1_diffuse.a;
		#endif
		
		colorLayer1.rgb *= baseColor.rgb;
		colorLayer1.a   *= (fs_layer1_alpha * layer_kOpacities.g);
		surfaceColor = combine(COMBINE_OP_1, colorLayer1, surfaceColor);
	#endif

	#if defined(COMBINE_OP_2)
		// texture blend 2
		#define USE_combine
		#pragma nu2_use(uniform, layer2_diffuse)
		#pragma nu2_use(fs_local, fs_layer2_alpha)
		
		#if defined(LAYER2_DIFFUSEENABLE)
			half4 colorLayer2 = layer2_diffuse;
		#else
			#pragma nu2_use(uniform, layer2_sampler)
			#pragma nu2_use(varying, * LAYER2_UVSET)
			#if defined(USE_fs_stOffset)
			half4 colorLayer2 = tex2D(layer2_sampler, LAYER2_UVSET + fs_stOffset);
			#else
			half4 colorLayer2 = tex2D(layer2_sampler, LAYER2_UVSET);
			#endif
			colorLayer2.a *= layer2_diffuse.a;
		#endif

		colorLayer2.rgb *= baseColor.rgb;
		colorLayer2.a   *= (fs_layer2_alpha * layer_kOpacities.b);
		surfaceColor = combine(COMBINE_OP_2, colorLayer2, surfaceColor);
	#endif

	#if defined(COMBINE_OP_3)
		// texture blend 3
		#define USE_combine
		#pragma nu2_use(uniform, layer3_diffuse)
		#pragma nu2_use(fs_local, fs_layer3_alpha)

		#if defined(LAYER3_DIFFUSEENABLE)
			half4 colorLayer3 = layer3_diffuse;
		#else
			#pragma nu2_use(uniform, layer3_sampler)
			#pragma nu2_use(varying, * LAYER3_UVSET)
			#if defined(USE_fs_stOffset)
			half4 colorLayer3 = tex2D(layer3_sampler, LAYER3_UVSET + fs_stOffset);
			#else
			half4 colorLayer3 = tex2D(layer3_sampler, LAYER3_UVSET);
			#endif
			colorLayer3.a *= layer3_diffuse.a;
		#endif
			
		colorLayer3.rgb *= baseColor.rgb;
		colorLayer3.a   *= (fs_layer3_alpha * layer_kOpacities.a);
		surfaceColor = combine(COMBINE_OP_3, colorLayer3, surfaceColor);
	#endif
	
	#if defined(DAPPLE)
		#pragma nu2_use(fs_local, fs_dappleFactor)
		surfaceColor.rgb *= fs_dappleFactor;
	#endif
	
	#if defined(FRACTAL)
		#pragma nu2_use(fs_local, fs_fbm0)
		#pragma nu2_use(uniform, fractal_params)
		surfaceColor.rgb *= (1.0 + fractal_params.a * fs_fbm0);
	#endif
	
	return surfaceColor;
}


