#endif

#if defined(FRESNEL_STAGE)
iNliNE half fresnelStage()
{
	#pragma nu2_use(uniform, specular_params)
	#pragma nu2_use(fs_local, fs_normal)
	#pragma nu2_use(fs_local, fs_incident)
	return lerp(specular_params.b, 1.0, pow(1.0 - dot(fs_normal, fs_incident), specular_params.a));
}

