iNliNE void func_pipePosition()
{
	#define USE_computeVertexSkin
	#pragma nu2_use(uniform, skinMatrix)
	#pragma nu2_use(uniform, viewProj)
	#pragma nu2_use(attribute, position)
	#pragma nu2_use(attribute, blendIndices0)
	#pragma nu2_use(attribute, blendWeight0)
	#pragma nu2_use(vs_local, vs_skinPosition)
	#pragma nu2_use(varying, varying_position)

	// skinning

	// rem: skinMatrix projects either from local space to local space (SKIN_WORLD),
	//      or from local space to world space (SKIN_WORLD is undefined)

	#if (VERTEX_SHADER_VERSION == 11)
		// VGP 02May2007 : Compensate for lack of UBYTE4 on GeForce3/4
		half4 blendIndices0 = D3DCOLORtoUBYTE4(vin.blendIndices0);
		half4 blendWeight0 = vin.blendWeight0.zyxw;
	#else
		half4 blendIndices0 = vin.blendIndices0;
		half4 blendWeight0 = vin.blendWeight0;
	#endif
	
	vs_skinPosition = computeVertexSkin(
		vin.position,
		skinMatrix[int(blendIndices0.x)],
		skinMatrix[int(blendIndices0.y)],
		skinMatrix[int(blendIndices0.z)],
		blendWeight0.x,
		blendWeight0.y,
		
		1.0 - blendWeight0.x - blendWeight0.y
	);

	#define USE_projectToClipSpace_forSkin

	#if defined(WIND)
		#define USE_computeWind
		#define USE_computeVertexWindOffsetTree
		varying_position = projectToClipSpace_forSkin(vs_skinPosition+computeVertexWindOffsetTree());
	#else
		varying_position = projectToClipSpace_forSkin(vs_skinPosition);
	#endif
}

