//	#if defined(RENDER_FOR_SHADOW)
//	if (varying_position.z/varying_position.w >= 0.8)
//		varying_position.y = varying_position.y * 0.5 - 0.5*varying_position.w;
//	else
//		varying_position.y = varying_position.y * 0.5 + 0.5*varying_position.w;
//	#endif
	
	#if defined(USE_varying_motionVector)
	func_pipeMotionVector();
	#endif

	#if defined(USE_varying_position2)
	pipePosition2();
	#endif

	#if defined(USE_varying_eyePosition)
	pipeEyePosition();
	#endif
	
	#if defined(USE_varying_waterAmplitude)
