#if defined(BUILD_PIXEL_SHADER)

FragmentOutput fragmentProgram(VertexOutput input)
{
	vout = input;

	// the compiler can optimize that
	#if (RENDER_TARGET_COUNT >= 2)
		fout.color[1] = float4(0.5, 0.5, 0.5, 1);
		#if (RENDER_TARGET_COUNT >= 3)
			fout.color[2] = half4(0.5, 0.5, 0.0, 0.0);
		#endif
	#endif
	
	#if defined(USE_fs_dappleFactor)
	fs_dappleFactor = func_fs_computeDappleFactor();
	#endif
	#if defined(USE_fs_pos)
	fs_pos = func_fs_computePos();
	#endif
	#if defined(USE_fs_vpos)
	fs_vpos = func_fs_computeVPos();
	#endif
	#if defined(USE_fs_nativeNormal)
	fs_nativeNormal = func_fs_computeNativeNormal();
	#endif
	#if defined(USE_fs_incident)
	fs_incident = func_fs_computeIncident();
	#endif
	#if defined(USE_fs_tangent)
	fs_tangent = func_fs_computeTangent();
	#endif
	#if defined(USE_fs_tangent2)
	fs_tangent2 = func_fs_computeTangent2();
	#endif
	#if defined(USE_fs_bitangent)
	fs_bitangent = func_fs_computeBitangent();
	#endif
	#if defined(USE_fs_bitangent2)
	fs_bitangent2 = func_fs_computeBitangent2();
	#endif
	#if defined(USE_fs_surfaceIncident)
	fs_surfaceIncident = func_fs_computeSurfaceIncident();
	#endif
	#if defined(USE_fs_surfaceIncident2)
	fs_surfaceIncident2 = func_fs_computeSurfaceIncident2();
	#endif
	#if defined(USE_fs_lightDir0)
	fs_lightDir0 = func_fs_computeLightDir0();
	#endif
	#if defined(USE_fs_lightDir1)
	fs_lightDir1 = func_fs_computeLightDir1();
	#endif
	#if defined(USE_fs_lightDir2)
	fs_lightDir2 = func_fs_computeLightDir2();
	#endif
	#if defined(USE_fs_fog_color)
	fs_fog_color = func_fs_computeFogColor();
	#endif
	
	#if defined(USE_fs_layer0_color)
	fs_layer0_color = func_fs_computeLayer0_color();
	#endif
	#if defined(USE_fs_layer1_alpha)
	fs_layer1_alpha = func_fs_computeLayer1_alpha();
	#endif
	#if defined(USE_fs_layer2_alpha)
	fs_layer2_alpha = func_fs_computeLayer2_alpha();
	#endif
	#if defined(USE_fs_layer3_alpha)
	fs_layer3_alpha = func_fs_computeLayer3_alpha();
	#endif
	#if defined(USE_fs_blend2)
	fs_blend2 = func_fs_computeBlend2();
	#endif
	
	#if defined(FUNC_fs_computeSurfaceNormal)
	fs_surfaceNormal = func_fs_computeSurfaceNormal();
	#endif
	#if defined(FUNC_fs_computeVTFNormal) && FUNC_fs_computeVTFNormal == VTF_SURFACE_NORMAL_MAP
	fs_vtfNormal = func_fs_computeVTFNormal();
	#endif
	#if defined(FUNC_fs_computeNormal)
	fs_normal = func_fs_computeNormal();
	#endif
	#if defined(FRACTAL)
	func_fs_fractalBump();
	#endif
	#if defined(FUNC_fs_computeTBN)
	fs_TBN = func_fs_computeTBN();
	#endif
	#if defined(USE_fs_worldReflection)
	fs_worldReflection = func_fs_computeWorldReflection();
	#endif
	#if defined(USE_fs_lightDirSet)
	fs_lightDirSet = func_fs_computeLightDirSet();
	#endif
	
	half4 surfaceColor = multiLayerBlendingStage();

	half4 reflectivityNoFresnel = 1.0;
	half4 reflectivity = 1.0;
	half fresnel = 1.0;
	
	#if defined(FRESNEL_STAGE) || defined(USE_fs_fresnel)
		fresnel = fresnelStage();
	#endif

	#if defined(REFLECTIVITY_STAGE)
		reflectivityNoFresnel = reflectivityStage();
		reflectivity = reflectivityNoFresnel * fresnel;
	#endif

	#if defined(LOD_SHADER)
		#pragma nu2_use(varying, varying_lodFactor)
		reflectivity *= varying_lodFactor;
	#endif
		
	half3 diffuseLight, specularLight;

	#if defined(USE_fs_ldotn0)
	fs_ldotn0 = func_fs_compute_ldotn0();
	#endif
	#if defined(USE_fs_ldotn0)
	fs_ldotn1 = func_fs_compute_ldotn1();
	#endif
	#if defined(USE_fs_ldotn0)
	fs_ldotn2 = func_fs_compute_ldotn2();
	#endif

	lightingStage(diffuseLight, specularLight);

	#if defined(GLOW_OUTPUT)
	// Glow for very bright specular
	float SpecularHDRGlow = max( dot( specularLight, float3(0.30,0.59,0.11) ) - 1.0, 0 );
	fout.color[1].a -= SpecularHDRGlow;
	#endif

	// Shade surface (includes refraction)
	fout.color[0] = surfaceShadingStage(surfaceColor,
										diffuseLight,
										specularLight * reflectivity,
										fresnel,
										reflectivityNoFresnel.a);

	#if defined(ENVMAP_STAGE)
		//#if defined(PRELIGHT_FX) && (PIXEL_SHADER_VERSION > 11)
		//	#pragma nu2_use(varying, varying_colorSet0)
		//	fout.color[0].rgb += (reflectivityNoFresnel * envmapStage(varying_colorSet0.rgb, fresnel));
		//#else
			fout.color[0].rgb += (reflectivityNoFresnel * envmapStage(diffuseLight, fresnel));
		//#endif
	#endif
	
	#if defined(FOG_STAGE)
		fogStage();
	#endif

	#if defined(RENDER_WHITE)
		fout.color[0] = 1.0; // the compiler just optimize to the core
	#endif

	#if defined(RENDER_RED)
		fout.color[0] = float4(1.0, 0.0, 0.0, 1.0); // the compiler just optimize to the core
	#endif
	
//#if defined(REFRACTION_STAGE) && REFRACTION_STAGE == REFRACTION_WATER
//	fout.color[0].xyz = varying_uvSetGlass;
//#endif
	
	#if defined(NORMAL_OUTPUT)	// deferred shading: write normal data and fragment z coordinate
		#if defined(NORMAL_OUTPUT_NOT_NULL)
			#pragma nu2_use(fs_local, fs_normal)
			#pragma nu2_use(fs_local, fs_nativeNormal)
			// VGP 07Aug2007 The .w of the vertex normal is 1 if we're rendering a shadow casting object,
			// and 0 otherwise. If we're not rendering a shadow caster, force the normals to be 0.5 to prevent
			// self-shading at the deferred shading stage.
			fout.color[NORMAL_OUTPUT].rgb = lerp(0.5, fs_normal * 0.5 + 0.5, fs_nativeNormal.w);
		#endif
	#endif
	
	#if defined(GLOW_OUTPUT)
		#pragma nu2_use(uniform, incandescentGlow)
		fout.color[1].a -= incandescentGlow.a;
	#endif

	#if defined (MOTION_OUTPUT)
		#pragma nu2_use(varying, varying_motionVector)
		#pragma nu2_use(fs_local, fs_pos)
		
		fout.color[MOTION_OUTPUT].rg = fs_pos.xy - (varying_motionVector.xy/varying_motionVector.z);

		// shift [-0.1; 0.1] to [0; 1] and also do the y inversion d3d requires us to do!
//		fout.color[MOTION_OUTPUT].rg /= half2(0.1, -0.1);
//		fout.color[MOTION_OUTPUT].rg = fout.color[MOTION_OUTPUT].rg * 0.5 + 0.5;
//		<=>
		fout.color[MOTION_OUTPUT].rg = fout.color[MOTION_OUTPUT].rg * half2(5.0, -5.0) + 0.5;

	#endif

	#if defined (DEPTHRT_OUTPUT)
		#pragma nu2_use(varying, varying_position2)
		float depth = varying_position2.z / varying_position2.w;
		fout.color[DEPTHRT_OUTPUT] = depth;
	#endif
	
	return fout;
}

