#if defined(USE_projectToClipSpace)
// projects a point in object local space to clip space
iNliNE float4 projectToClipSpace(float4 position)
{
	#if defined (_360_TARGET) || defined(_WINPC)
		// on the 360 computing worldView and worldViewProj on the CPU costs a lot (up to 10% of
		//  the cpu frame time), so we are doing it on the GPU instead (original shader code
		// pre-uberShader was doing the same!).
		#pragma nu2_use(uniform, world)
		#pragma nu2_use(uniform, viewProj)
		return mul (mul(position, world), viewProj);
	#else
		#pragma nu2_use(uniform, worldViewProj)
		return mul(position, worldViewProj);
	#endif
}

//__________________________________________________________________________________________________
#endif

