		//  the cpu frame time), so we are doing it on the GPU instead (original shader code
		// pre-uberShader was doing the same!).
		#pragma nu2_use(uniform, world)
		#pragma nu2_use(uniform, viewProj)
		return mul (mul(position, world), viewProj);
	#else
		#if defined(SKIN_WORLD)
			#pragma nu2_use(uniform, worldViewProj)
			return mul(position, worldViewProj);
		#else
			#pragma nu2_use(uniform, viewProj)
