#if defined (USE_combine)
iNliNE half4 combine(in int blendOp, in half4 src, in half4 dst)
{
	if (blendOp == COMBINE_OVER)
		return half4(
			dst.rgb * (1.0 - src.a) + src.rgb * src.a,
			1.0 - ((1.0 - dst.a) * (1.0 - src.a))
		);
	else if (blendOp == COMBINE_ADD)
		return half4(dst.rgb + src.rgb * src.a, dst.a);
	else if (blendOp == COMBINE_SUBTRACT)
		return half4(dst.rgb - src.rgb * src.a, dst.a);
	else if (blendOp == COMBINE_MULTIPLY)
		return half4(dst.rgb * (src.rgb * src.a + half3(1.0-src.a, 1.0-src.a, 1.0-src.a)), dst.a);
	else
		return dst;
}

