	half3 t0 = mul(bitangent, (float3x3)skinMatrix[blendIndices0.x]);
	half3 t1 = mul(bitangent, (float3x3)skinMatrix[blendIndices0.y]);
	half3 t2 = mul(bitangent, (float3x3)skinMatrix[blendIndices0.z]);
	half3 b = normalize(
